def _parse(version):
    """Return a sort key for a semantic version string."""
    # Build metadata is ignored for precedence.
    core = version.split('+', 1)[0]

    if '-' in core:
        main, pre = core.split('-', 1)
        pre_ids = pre.split('.') if pre != '' else []
    else:
        main, pre_ids = core, None

    major, minor, patch = (int(p) for p in main.split('.'))

    if pre_ids is None:
        # No pre-release: higher precedence than any pre-release of same core.
        pre_key = (1,)
    else:
        ids = []
        for ident in pre_ids:
            if ident.isdigit():
                ids.append((0, int(ident)))
            else:
                ids.append((1, ident))
        pre_key = (0, tuple(ids))

    return (major, minor, patch, pre_key)


def sort_versions(vs):
    """Sort semantic version strings by precedence, lowest first.

    Ties keep their original input order (stable sort).
    """
    return sorted(vs, key=_parse)
